import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"Keelhaven and the alternatives","description":"How Keelhaven compares with Time Machine, Arq, Backblaze Computer Backup, the restic command line, Backrest and Vorta — and when each of them is the better choice for backing up a Mac.","frontmatter":{"title":"Keelhaven and the alternatives","description":"How Keelhaven compares with Time Machine, Arq, Backblaze Computer Backup, the restic command line, Backrest and Vorta — and when each of them is the better choice for backing up a Mac."},"headers":[],"relativePath":"compare.md","filePath":"compare.md"}'),n={name:"compare.md"};function d(s,e,i,h,c,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="keelhaven-and-the-alternatives" tabindex="-1">Keelhaven and the alternatives <a class="header-anchor" href="#keelhaven-and-the-alternatives" aria-label="Permalink to &quot;Keelhaven and the alternatives&quot;">​</a></h1><p>Keelhaven does one thing: it keeps an encrypted copy of the folders you choose on storage that is yours. Several good tools overlap with that, and some of them will suit you better.</p><table tabindex="0"><thead><tr><th></th><th>Price</th><th>Open source</th><th>Stores to</th><th>Runs as</th></tr></thead><tbody><tr><td><strong>Keelhaven</strong></td><td>Free</td><td>Yes</td><td>Your drive, bucket or server</td><td>Mac menu bar app</td></tr><tr><td><strong>Time Machine</strong></td><td>Comes with macOS</td><td>No</td><td>A drive or network disk</td><td>Part of macOS</td></tr><tr><td><strong>Arq</strong></td><td>Paid licence</td><td>No</td><td>Your drive, server or cloud account</td><td>Mac and Windows app</td></tr><tr><td><strong>Backblaze Computer Backup</strong></td><td>Subscription</td><td>No</td><td>Backblaze</td><td>Mac and Windows app</td></tr><tr><td><strong>restic</strong></td><td>Free</td><td>Yes</td><td>Your drive, bucket or server</td><td>Command line</td></tr><tr><td><strong>Backrest</strong></td><td>Free</td><td>Yes</td><td>Anything restic can reach</td><td>Web page served from your machine</td></tr><tr><td><strong>Vorta</strong></td><td>Free</td><td>Yes</td><td>A drive, or a server running Borg</td><td>Mac and Linux app</td></tr></tbody></table><h2 id="time-machine" tabindex="-1">Time Machine <a class="header-anchor" href="#time-machine" aria-label="Permalink to &quot;Time Machine&quot;">​</a></h2><p>Run both. Time Machine puts a whole Mac back the way it was, from a drive on your desk. Keelhaven is the second copy: the folders you cannot lose, encrypted, somewhere that is not your desk.</p><h2 id="arq" tabindex="-1">Arq <a class="header-anchor" href="#arq" aria-label="Permalink to &quot;Arq&quot;">​</a></h2><p>The closest in idea: your files, your storage, your key. Arq has been doing it longer, runs on Windows too, and backs up to Google Drive, OneDrive and Dropbox.</p><p>Choose Keelhaven if you want it free and open source, with backups in a format other tools can read.</p><h2 id="backblaze-computer-backup" tabindex="-1">Backblaze Computer Backup <a class="header-anchor" href="#backblaze-computer-backup" aria-label="Permalink to &quot;Backblaze Computer Backup&quot;">​</a></h2><p>The least effort there is: one subscription, the whole computer, their storage. Choose it if you would rather pay someone to own the problem.</p><p>Choose Keelhaven if you want to decide where the data lives, or already have a NAS or a bucket.</p><h2 id="restic" tabindex="-1">restic <a class="header-anchor" href="#restic" aria-label="Permalink to &quot;restic&quot;">​</a></h2><p>restic is Keelhaven&#39;s engine. If a launchd job and a password in a script suit you, you do not need Keelhaven.</p><p>It adds what a command-line tool leaves to you: a schedule that runs, secrets in the Keychain, and a notification when something breaks. The repository stays plain restic — see <a href="/restic">Keelhaven for restic users</a>.</p><h2 id="backrest" tabindex="-1">Backrest <a class="header-anchor" href="#backrest" aria-label="Permalink to &quot;Backrest&quot;">​</a></h2><p>Also a front end for restic, used from a browser. It runs on Linux, in Docker and on a NAS as well as on a Mac, and exposes more of restic than Keelhaven does. Choose it for a server, or if you want every setting.</p><p>Choose Keelhaven for a Mac you would rather not think about: a native app, nothing to open in a browser, defaults that are already right.</p><h2 id="vorta" tabindex="-1">Vorta <a class="header-anchor" href="#vorta" aria-label="Permalink to &quot;Vorta&quot;">​</a></h2><p>A desktop app like Keelhaven, built on BorgBackup instead of restic. Borg wants a drive, or a server it can run on, rather than a plain bucket. Choose it if you already use Borg.</p>',19)])])}const m=t(n,[["render",d]]);export{u as __pageData,m as default};
